INSERT INTO `fake_sites` (`id`, `template_id`, `title`, `paragraph1`, `paragraph2`) VALUES
(2005, 1, 'W Finlandii niedźwiedź został prezydentem', 'Świat był w szoku, kiedy wiadomość ta obiegła wszystkie media. Mieszkańcy byli zdezorientowani, a eksperci próbowali zrozumieć, jak do tego doszło. Niektórzy uważają, że był to wynik serii nieprawdopodobnych zbiegów okoliczności, inni doszukują się większego planu.', 'Świat był w szoku, kiedy wiadomość ta obiegła wszystkie media. Mieszkańcy byli zdezorientowani, a eksperci próbowali zrozumieć, jak do tego doszło. Niektórzy uważają, że był to wynik serii nieprawdopodobnych zbiegów okoliczności, inni doszukują się większego planu.'),
(2006, 1, 'W Finlandii niedźwiedź został prezydentem', 'Według świadków wydarzenie miało miejsce o świcie, kiedy większość ludzi jeszcze spała. Lokalna społeczność zareagowała natychmiastowo, organizując protesty i pikniki. Specjaliści ostrzegają, że konsekwencje tego działania mogą być zarówno śmieszne, jak i zaskakujące.', 'Według świadków wydarzenie miało miejsce o świcie, kiedy większość ludzi jeszcze spała. Lokalna społeczność zareagowała natychmiastowo, organizując protesty i pikniki. Specjaliści ostrzegają, że konsekwencje tego działania mogą być zarówno śmieszne, jak i zaskakujące.'),
